    67	  assert.throws(() => normalize(null), { code: 'NOT_A_STRING', message: 'path must be a string' });
    68	  assert.throws(() => normalize('a\u0000b'), { code: 'NUL_BYTE', message: 'path contains a NUL byte' });
    69	  assert.throws(() => normalize('/..'), { code: 'ESCAPE', message: 'path escapes root: /..' });
    70	  assert.throws(() => normalize('/../a'), { code: 'ESCAPE', message: 'path escapes root: /../a' });
