   102	  const cases = [
   103	    ['/a/b', '/a/b', ''],
   104	    ['/a/b', '/a/b/c/d', 'c/d'],
   105	    ['/a/b/c', '/a/d', '../../d'],
   106	    ['/', '/a/b', 'a/b'],
   107	    ['/a/b', '/', '../..'],
   108	    ['/a/b/', '/a/c', '../c'],
   109	    ['/a/./b', '/a/b/c', 'c'],
   110	    ['/x', '/y', '../y'],
   111	    ['/a/bb', '/a/b', '../b'],
   112	    ['/日本/a', '/日本/b', '../b'],
   113	  ];
   114	  for (const [from, to, expected] of cases) {
   115	    assert.equal(relative(from, to), expected, `relative(${from}, ${to})`);
   116	  }
