   119	test('relative demands two absolute paths', () => {
   120	  assert.throws(() => relative('a', '/b'), { code: 'NOT_ABSOLUTE', message: 'both paths must be absolute' });
   121	  assert.throws(() => relative('/a', 'b'), { code: 'NOT_ABSOLUTE', message: 'both paths must be absolute' });
   122	  assert.throws(() => relative('', '/b'), { code: 'NOT_ABSOLUTE' });
   123	  assert.throws(() => relative('/..', '/a'), { code: 'ESCAPE' });
   124	  assert.throws(() => relative('/a', undefined), { code: 'NOT_A_STRING' });
   125	  assert.throws(() => relative('/a\u0000', '/b'), { code: 'NUL_BYTE' });
   126	});
   127	
   128	test('normalized paths are stable and well formed for generated input', () => {
   129	  const pick = mulberry32(555);
   130	  const parts = ['a', 'bb', '.', '..', 'c', '日', 'x.y', '..a'];
   131	  for (let round = 0; round < 400; round += 1) {
   132	    const rooted = pick() < 0.5;
   133	    const count = 1 + Math.floor(pick() * 6);
   134	    const chosen = Array.from({ length: count }, () => parts[Math.floor(pick() * parts.length)]);
   135	    const raw = (rooted ? '/' : '') + chosen.join(pick() < 0.2 ? '//' : '/');
   136	    let result;
   137	    try {
   138	      result = normalize(raw);
   139	    } catch (error) {
   140	      assert.equal(error.code, 'ESCAPE', `only rooted escapes may throw for ${raw}`);
   141	      assert.equal(rooted, true, `relative paths never escape: ${raw}`);
   142	      continue;
   143	    }
   144	    assert.equal(normalize(result), result, `idempotent for ${raw}`);
   145	    assert.equal(result.includes('//'), false, `no doubled separator in ${result}`);
   146	    assert.equal(result === '/' || result.endsWith('/'), result === '/', `no trailing slash in ${result}`);
   147	    assert.equal(result.startsWith('/'), rooted, `rootedness preserved for ${raw}`);
   148	    assert.notEqual(result, '', 'never empty');
   149	  }
   150	});
   151	
   152	test('relative and join are inverses for generated absolute paths', () => {
   153	  const pick = mulberry32(777);
   154	  const parts = ['a', 'b', 'c', 'dd', '日'];
   155	  const makePath = () => {
   156	    const count = Math.floor(pick() * 5);
   157	    return `/${Array.from({ length: count }, () => parts[Math.floor(pick() * parts.length)]).join('/')}`;
   158	  };
   159	  for (let round = 0; round < 300; round += 1) {
   160	    const from = normalize(makePath());
   161	    const to = normalize(makePath());
   162	    const step = relative(from, to);
   163	    assert.equal(isAbsolute(step), false, `${step} is relative`);
   164	    assert.equal(join(from, step === '' ? '.' : step), to, `join(${from}, ${step}) returns ${to}`);
   165	    assert.equal(relative(from, from), '', 'a path is empty relative to itself');
   166	    if (step !== '') assert.equal(normalize(step), step, `${step} is already normalized`);
   167	  }
   168	});

